import 'package:decimal/decimal.dart';

import '../../data/models/models.dart';
import 'api_client.dart';

/// Transfer operations: internal (real ledger) and external (gated by the
/// payment gateway). Idempotency keys are generated by the caller.
class TransferService {
  TransferService._();
  static final TransferService instance = TransferService._();

  Future<Map<String, dynamic>> internal({
    required String destinationAccountNumber,
    required Decimal amount,
    required String idempotencyKey,
    String? reference,
  }) async =>
      ApiClient.post('/transfers/internal', {
        'destination_account_number': destinationAccountNumber,
        'amount': amount.toString(),
        'idempotency_key': idempotencyKey,
        if (reference != null) 'reference': reference,
      });

  Future<Map<String, dynamic>> external({
    required String destinationName,
    required String destinationDocument,
    required String destinationBankCode,
    required String destinationAccountNumber,
    required String destinationAccountDigit,
    required Decimal amount,
    required String idempotencyKey,
    String? reference,
  }) async =>
      ApiClient.post('/transfers/external', {
        'destination_name': destinationName,
        'destination_document': destinationDocument,
        'destination_bank_code': destinationBankCode,
        'destination_account_number': destinationAccountNumber,
        'destination_account_digit': destinationAccountDigit,
        'amount': amount.toString(),
        'idempotency_key': idempotencyKey,
        if (reference != null) 'reference': reference,
      });

  Future<List<Transaction>> history({int limit = 50}) async {
    final data = await ApiClient.getList('/accounts/transactions',
        {'limit': limit.toString()});
    return data.map(Transaction.fromJson).toList();
  }

  Future<Transaction> transaction(String id) async =>
      Transaction.fromJson(await ApiClient.get('/pix/transactions/$id'));
}
